package com.ke.ticketsystemke.repository;import com.ke.ticketsystemke.entity.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;
public interface WarrantyReminderRepository extends JpaRepository<WarrantyReminder,Long>{@EntityGraph(attributePaths={"warrantyClaim","ticket"})@Query("select r from WarrantyReminder r")List<WarrantyReminder> findAllDetailed();Optional<WarrantyReminder> findByDeduplicationKey(String key);@Query("select r from WarrantyReminder r where r.status in :statuses")List<WarrantyReminder> findByStatusIn(@Param("statuses")Collection<WarrantyReminderStatus> statuses);}
